import java.util.*;

class Solution {
    public int maximalRectangle(char[][] roof) {
        int cols = roof[0].length, best = 0;
        int[] h = new int[cols];
        for (char[] row : roof) {
            for (int c = 0; c < cols; c++) h[c] = (row[c] == '1') ? h[c] + 1 : 0;  // column heights
            best = Math.max(best, largestInHistogram(h));
        }
        return best;
    }

    private int largestInHistogram(int[] h) {
        int n = h.length, best = 0, top = -1;
        int[] st = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            int cur = (i == n) ? 0 : h[i];
            while (top >= 0 && h[st[top]] >= cur) {
                int height = h[st[top--]];
                int left = (top >= 0) ? st[top] + 1 : 0;
                best = Math.max(best, height * (i - left));
            }
            st[++top] = i;
        }
        return best;
    }
}

