class Solution:
    def maximalRectangle(self, roof: List[List[str]]) -> int:
        cols = len(roof[0]); h = [0] * cols; best = 0
        for row in roof:
            for j in range(cols): h[j] = h[j] + 1 if row[j] == "1" else 0
            st = []
            for i, x in enumerate(h + [0]):
                while st and h[st[-1]] >= x:
                    t = h[st.pop()]
                    best = max(best, t * (i - (st[-1] + 1 if st else 0)))
                st.append(i)
        return best

