function maximalRectangle(roof) {
  // O(rows^2 * cols): fix top and bottom rows, scan columns that are all ones
  const m = roof.length, n = roof[0].length; let best = 0;
  for (let top = 0; top < m; top++) {
    const all = new Array(n).fill(true);
    for (let bot = top; bot < m; bot++) {
      let run = 0;
      for (let j = 0; j < n; j++) {
        all[j] = all[j] && roof[bot][j] === "1";
        run = all[j] ? run + 1 : 0;
        best = Math.max(best, run * (bot - top + 1));
      }
    }
  }
  return best;
}
